@import url('https://fonts.googleapis.com/css2?family=Source+Sans+3:wght@300;400;500;600;700&display=swap');

/* Override Tailwind theme variables */
.lmo {
    --tw-primary: 24, 100%, 50% !important;
    --tw-primary-foreground: 0, 0%, 100% !important;
    --tw-background: 0, 0%, 100% !important;
    --tw-surface: 0, 0%, 100% !important;
    --tw-surface-main: 0, 0%, 95% !important;
    --tw-foreground: 0, 0%, 10% !important;
    --tw-card: 0, 0%, 100% !important;
    --tw-card-foreground: 0, 0%, 10% !important;
    --tw-border: 0, 0%, 88% !important;
    --tw-text-primary: 0, 0%, 10% !important;
    --tw-text-secondary: 0, 0%, 33% !important;
    --tw-text-tertiary: 0, 0%, 54% !important;
    --tw-form-accent: 24, 100%, 50% !important;
    --tw-form-focus: 24, 100%, 50% !important;
    --tw-ring: 24, 100%, 50% !important;
}

/* Base font */
body, .lmb, .lmo {
    font-family: 'Source Sans 3', 'Helvetica Neue', Helvetica, Arial, sans-serif !important;
    color: #1A1A1A !important;
}

/* Navbar */
.navbar {
    background-color: white !important;
    font-family: 'Source Sans 3', sans-serif !important;
    font-size: 1.2em;
    padding-bottom: 12px;
    border-bottom: 1px solid #e0e0e0 !important;
}

/* Headings - "Your New Cart" and "Your Changes" */
h2 {
    font-family: 'Source Sans 3', sans-serif !important;
    font-weight: 700 !important;
    color: #1A1A1A !important;
}

/* "Compatible add-ons" heading */
h1 {
    font-family: 'Source Sans 3', sans-serif !important;
    font-weight: 700 !important;
    color: #1A1A1A !important;
}

/* Total heading */
h3 {
    font-family: 'Source Sans 3', sans-serif !important;
    color: #1A1A1A !important;
}

/* Cart item text */
[data-testid="item-description"] span {
    font-family: 'Source Sans 3', sans-serif !important;
}
[data-testid="item-price"] span {
    font-family: 'Source Sans 3', sans-serif !important;
}

/* Quantity select */
[data-testid="item-quantity"] {
    font-family: 'Source Sans 3', sans-serif !important;
    border-radius: 2px !important;
}

/* Add-on cards - sharp corners */
[data-testid="card"] {
    border-radius: 2px !important;
    border-color: #e0e0e0 !important;
}
[data-testid="card"] div,
[data-testid="card"] span,
[data-testid="card"] p {
    font-family: 'Source Sans 3', sans-serif !important;
}

/* Add button on add-on cards */
[data-testid="card"] button {
    border-color: #FF6600 !important;
    color: #FF6600 !important;
    border-radius: 2px !important;
    font-family: 'Source Sans 3', sans-serif !important;
    font-weight: 600 !important;
}

/* Right sidebar text */
.tw-bg-surface-main span,
.tw-bg-surface-main div {
    font-family: 'Source Sans 3', sans-serif !important;
}

/* Billing schedule card */
.tw-rounded-lg.tw-text-card-foreground {
    border-radius: 2px !important;
    border-color: #e0e0e0 !important;
    font-family: 'Source Sans 3', sans-serif !important;
}

/* Submit button */
button[type="submit"] {
    background-color: #FF6600 !important;
    color: white !important;
    font-family: 'Source Sans 3', sans-serif !important;
    font-weight: 700 !important;
    font-size: 1rem !important;
    text-transform: uppercase !important;
    letter-spacing: 0.5px !important;
    border: none !important;
    border-radius: 2px !important;
    padding: 12px 30px !important;
    width: 100% !important;
}
button[type="submit"]:hover {
    background-color: #e55c00 !important;
}

/* Self-service form */
form[name="self-service-form"] {
    font-family: 'Source Sans 3', sans-serif !important;
}

/* Links */
a {
    color: #037EAF !important;
}
nav a {
    color: inherit !important;
}

