/* Sleek action buttons for Subscriptions card */
#orders-table-limio .MuiCardContent-root .MuiButton-root {
  --btn-radius: 12px;
  --btn-border: #e5e7eb;         /* subtle border */
  --btn-text: #0f172a;           /* slate-900-ish */
  --btn-text-muted: #334155;     /* slate-700-ish */
  --btn-bg: #ffffff;
  --btn-bg-hover: #f8fafc;       /* very light */
  --btn-shadow: 0 1px 2px rgba(16, 24, 40, 0.08),
                0 1px 1px rgba(16, 24, 40, 0.06);

  border-radius: var(--btn-radius);
  padding: 10px 14px;
  line-height: 1.1;
  font-weight: 600;
  letter-spacing: 0;
  border: 1px solid var(--btn-border);
  background: var(--btn-bg);
  color: var(--btn-text);
  box-shadow: var(--btn-shadow);
  transition: background-color .18s ease, border-color .18s ease,
              transform .06s ease, box-shadow .18s ease, color .18s ease;
}

/* Icon alignment & size */
#orders-table-limio .MuiCardContent-root .MuiButton-root .MuiButton-startIcon {
  margin-right: 8px;
}
#orders-table-limio .MuiCardContent-root .MuiButton-root svg {
  width: 20px; height: 20px;
}

/* Hover / focus */
#orders-table-limio .MuiCardContent-root .MuiButton-root:hover {
  background: var(--btn-bg-hover);
  border-color: #d1d5db;
  transform: translateY(-1px);
  box-shadow: 0 6px 14px rgba(16, 24, 40, 0.10),
              0 2px 6px rgba(16, 24, 40, 0.06);
}
#orders-table-limio .MuiCardContent-root .MuiButton-root:focus-visible {
  outline: none;
  box-shadow:
    0 0 0 4px rgba(59, 130, 246, 0.15),
    var(--btn-shadow);
}

/* Active */
#orders-table-limio .MuiCardContent-root .MuiButton-root:active {
  transform: translateY(0);
  box-shadow: 0 1px 2px rgba(16, 24, 40, 0.12);
}

/* “Outlined primary” (Update Plan / Edit Add-Ons) as modern ghost buttons */
#orders-table-limio .MuiButton-outlinedPrimary {
  color: var(--btn-text-muted);
  background: var(--btn-bg);
  border-color: var(--btn-border);
}
#orders-table-limio .MuiButton-outlinedPrimary:hover {
  color: var(--btn-text);
}

/* “Contained error” (Cancel) softened to premium destructive */
#orders-table-limio .MuiButton-containedError {
  --destructive: #ef4444;
  --destructive-hover: #dc2626;
  color: #fff;
  border-color: transparent;
  background: var(--destructive);
  box-shadow: 0 2px 6px rgba(239, 68, 68, 0.35);
}
#orders-table-limio .MuiButton-containedError:hover {
  background: var(--destructive-hover);
  box-shadow: 0 8px 18px rgba(239, 68, 68, 0.35);
}

/* Make the 3 buttons feel like a unified action bar */
#orders-table-limio .MuiCardContent-root .MuiStack-root > .MuiButton-root {
  min-height: 42px;
}

/* Optional: tone down the MUI ripple for a cleaner feel */
#orders-table-limio .MuiCardContent-root .MuiButton-root .MuiTouchRipple-child {
  opacity: 0.12;
}



