/* Form container */
form[name="data-capture-form"] {
  border-radius: 1rem !important;
  border: 1px solid rgb(226 232 240) !important;
  background: white !important;
  padding: 1.5rem !important;
  box-shadow: 0 1px 2px rgba(0,0,0,0.04), 0 8px 24px rgba(0,0,0,0.06) !important;
}

/* Layout rhythm */
form[name="data-capture-form"] > fieldset {
  display: flex !important;
  flex-direction: column !important;
  gap: 1.25rem !important;
}

/* Remove bootstrap spacing */
form[name="data-capture-form"] .tw-pt-4 {
  padding-top: 0 !important;
}

/* Field groups */
form[name="data-capture-form"] .form-group,
form[name="data-capture-form"] .select-group {
  display: flex !important;
  flex-direction: column !important;
  gap: 0.35rem !important;
}

/* Labels */
form[name="data-capture-form"] label,
form[name="data-capture-form"] legend {
  font-size: 0.875rem !important;
  font-weight: 500 !important;
  color: rgb(30 41 59) !important;
  margin-bottom: 0.25rem !important;
  display: block !important;
}

/* Select input */
form[name="data-capture-form"] select {
  width: 100% !important;
  height: 44px !important;
  border-radius: 0.75rem !important;
  border: 1px solid rgb(203 213 225) !important;
  background: white !important;
  padding: 0 1rem !important;
  padding-right: 2.5rem !important;
  font-size: 0.875rem !important;
  color: rgb(15 23 42) !important;
  box-shadow: 0 1px 2px rgba(0,0,0,0.04) !important;
  transition: all 0.15s ease !important;
  appearance: none !important;
}

/* Select hover */
form[name="data-capture-form"] select:hover {
  border-color: rgb(100 116 139) !important;
}

/* Select focus */
form[name="data-capture-form"] select:focus {
  outline: none !important;
  border-color: rgb(15 23 42) !important;
  box-shadow: 0 0 0 4px rgba(148,163,184,0.25) !important;
}

/* Custom dropdown arrow */
form[name="data-capture-form"] select {
  background-image:
    linear-gradient(45deg, transparent 50%, currentColor 50%),
    linear-gradient(135deg, currentColor 50%, transparent 50%) !important;
  background-position:
    calc(100% - 18px) calc(50% - 2px),
    calc(100% - 12px) calc(50% - 2px) !important;
  background-size: 6px 6px, 6px 6px !important;
  background-repeat: no-repeat !important;
}

/* Checkbox panel */
form[name="data-capture-form"] #customerDetails.contact-field > fieldset {
  border: 1px solid rgb(226 232 240) !important;
  border-radius: 0.75rem !important;
  background: rgb(248 250 252) !important;
  padding: 1rem !important;
}

/* Checkbox row */
form[name="data-capture-form"] #customerDetails.contact-field .form-group {
  display: flex !important;
  align-items: flex-start !important;
  gap: 0.6rem !important;
  border: 1px solid rgb(226 232 240) !important;
  border-radius: 0.5rem !important;
  background: white !important;
  padding: 0.75rem !important;
}

/* Checkbox */
form[name="data-capture-form"] input[type="checkbox"] {
  width: 18px !important;
  height: 18px !important;
  border-radius: 0.4rem !important;
  border: 1px solid rgb(203 213 225) !important;
  cursor: pointer !important;
}

/* Checkbox focus */
form[name="data-capture-form"] input[type="checkbox"]:focus {
  outline: none !important;
  box-shadow: 0 0 0 4px rgba(148,163,184,0.25) !important;
}

/* Checkbox label text */
form[name="data-capture-form"] input[type="checkbox"] + label {
  font-size: 0.875rem !important;
  font-weight: 500 !important;
  color: rgb(51 65 85) !important;
  margin: 0 !important;
}

/* Remove extra paragraph spacing */
form[name="data-capture-form"] label p {
  margin: 0 !important;
}

/* Submit button */
form[name="data-capture-form"] button[type="submit"] {
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  height: 44px !important;
  padding: 0 1.25rem !important;
  border-radius: 0.75rem !important;
  background: rgb(15 23 42) !important;
  color: white !important;
  font-size: 0.875rem !important;
  font-weight: 600 !important;
  border: none !important;
  transition: all 0.15s ease !important;
}

/* Button hover */
form[name="data-capture-form"] button[type="submit"]:hover {
  background: rgb(30 41 59) !important;
  box-shadow: 0 6px 18px rgba(0,0,0,0.12) !important;
}

/* Button focus */
form[name="data-capture-form"] button[type="submit"]:focus {
  outline: none !important;
  box-shadow: 0 0 0 4px rgba(148,163,184,0.3) !important;
}

