/* ─────────────────────────────────────────────────────────────────
   1. Hide the data-capture form's hardcoded Submit button
      (we drive checkout from the dedicated Continue button below)
   ───────────────────────────────────────────────────────────────── */
form[name="data-capture-form"] > button[type="submit"] {
  display: none !important;
}

/* ─────────────────────────────────────────────────────────────────
   2. Propelus-style page chrome
   ───────────────────────────────────────────────────────────────── */

/* Soft white surfaces, no harsh column tint */
.lmo .tw-bg-surface,
.lmo .tw-bg-surface-main {
  background-color: #ffffff !important;
}
.lmo .lg\:tw-border-l { border-color: #e5e9ee !important; }

/* Step headings ("1. Enter your license", "Your Course") */
.lmo h2 {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto,
               "Helvetica Neue", Arial, sans-serif !important;
  font-size: 17px !important;
  font-weight: 700 !important;
  color: #1a3a6c !important;        /* propelus navy */
  margin-bottom: 14px !important;
  letter-spacing: 0 !important;
}

/* License number — clean underline-only input */
form[name="data-capture-form"] input {
  border: none !important;
  border-bottom: 1px solid #c4c8cf !important;
  border-radius: 0 !important;
  background: transparent !important;
  padding: 8px 0 !important;
  font-size: 15px !important;
  color: #1f2933 !important;
  transition: border-color 0.2s ease !important;
}
form[name="data-capture-form"] input:focus {
  outline: none !important;
  border-bottom: 2px solid #1a3a6c !important;
}
form[name="data-capture-form"] label {
  font-size: 13px !important;
  color: #6b7280 !important;
  font-weight: 500 !important;
}

/* Primary CTA (Continue) — propelus green, rounded, tightened type */
.lmo .tw-bg-primary {
  background-color: #00a846 !important;
  color: #ffffff !important;
  border-radius: 4px !important;
  font-weight: 600 !important;
  font-size: 14px !important;
  padding: 10px 24px !important;
  text-transform: none !important;
  transition: background-color 0.15s ease !important;
}
.lmo .tw-bg-primary:hover { background-color: #008a3a !important; }

/* Testimonial: small italic quote, no boxy card */
.lmo .*\:tw-m-0 p {
  font-style: italic;
  color: #4b5563;
  line-height: 1.6;
}

/* Tighten the cart item layout */
.lmo [data-testid="cart-item"] { gap: 16px; }
.lmo [data-testid="item-price"] {
  color: #1a3a6c !important;
  font-weight: 700 !important;
}

/* "Add a subscription?" sub-heading */
.lmo h2.tw-text-2xl {
  font-size: 17px !important;
  color: #1a3a6c !important;
}

